class Solution:
    def licenseKeyFormatting(self, s: str, k: int) -> str:
        s = s.replace('-', '').upper()
        first = len(s) % k
        parts = []
        if first: parts.append(s[:first])
        for i in range(first, len(s), k):
            parts.append(s[i:i+k])
        return '-'.join(parts)

class Solution:
    def smallestGoodBase(self, n: str) -> str:
        num = int(n)
        for m in range(num.bit_length(), 2, -1):
            lo, hi = 2, int(num**(1/(m-1))) + 1
            while lo <= hi:
                mid = (lo + hi) // 2
                val = (mid**m - 1) // (mid - 1)
                if val == num: return str(mid)
                elif val < num: lo = mid + 1
                else: hi = mid - 1
        return str(num - 1)

