class Solution:
    def findMinStep(self, board: str, hand: str) -> int:
        from functools import lru_cache
        def remove(s):
            while True:
                new_s = ''
                i = 0
                changed = False
                while i < len(s):
                    j = i
                    while j < len(s) and s[j] == s[i]: j += 1
                    if j - i >= 3: changed = True
                    else: new_s += s[i:j]
                    i = j
                s = new_s
                if not changed: break
            return s
        hand_sorted = ''.join(sorted(hand))
        @lru_cache(maxsize=None)
        def dfs(board, hand):
            if not board: return 0
            if not hand: return float('inf')
            res = float('inf')
            for i in range(len(hand)):
                if i > 0 and hand[i] == hand[i-1]: continue
                for j in range(len(board)):
                    if board[j] != hand[i]: continue
                    new_board = remove(board[:j] + hand[i] + board[j:])
                    new_hand = hand[:i] + hand[i+1:]
                    sub = dfs(new_board, new_hand)
                    if sub != float('inf'):
                        res = min(res, 1 + sub)
            return res
        ans = dfs(board, hand_sorted)
        return ans if ans != float('inf') else -1

class Solution:
    def hasPath(self, maze, start, destination) -> bool:
        from collections import deque
        m, n = len(maze), len(maze[0])
        visited = set()
        visited.add(tuple(start))
        q = deque([start])
        while q:
            x, y = q.popleft()
            if [x,y] == destination: return True
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = x, y
                while 0<=nx+dx<m and 0<=ny+dy<n and maze[nx+dx][ny+dy]==0:
                    nx += dx; ny += dy
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    q.append([nx, ny])
        return False

class Solution:
    def findSubsequences(self, nums: list[int]) -> list[list[int]]:
        res = []
        def bt(start, path):
            if len(path) >= 2: res.append(path[:])
            used = set()
            for i in range(start, len(nums)):
                if nums[i] in used: continue
                if path and nums[i] < path[-1]: continue
                used.add(nums[i])
                path.append(nums[i])
                bt(i+1, path)
                path.pop()
        bt(0, [])
        return res

