class Solution:
    def findRotateSteps(self, ring: str, key: str) -> int:
        from functools import lru_cache
        n = len(ring)
        @lru_cache(maxsize=None)
        def dp(ki, ri):
            if ki == len(key): return 0
            res = float('inf')
            for j in range(n):
                if ring[j] == key[ki]:
                    diff = abs(ri - j)
                    step = min(diff, n - diff)
                    res = min(res, step + 1 + dp(ki+1, j))
            return res
        return dp(0, 0)

class Solution:
