class Solution:
    def checkSubarraySum(self, nums: list[int], k: int) -> bool:
        mod_map = {0: -1}
        prefix_mod = 0
        for i, n in enumerate(nums):
            prefix_mod = (prefix_mod + n) % k
            if prefix_mod in mod_map:
                if i - mod_map[prefix_mod] >= 2: return True
            else:
                mod_map[prefix_mod] = i
        return False

class Solution:
    def findLongestWord(self, s: str, dictionary: list[str]) -> str:
        def is_sub(word):
            i = 0
            for c in s:
                if i < len(word) and c == word[i]: i += 1
            return i == len(word)
        res = ''
        for w in dictionary:
            if is_sub(w):
