class Solution:
    def countArrangement(self, n: int) -> int:
        self.count = 0
        visited = [False] * (n + 1)
        def bt(pos):
            if pos > n:
                self.count += 1
                return
            for num in range(1, n+1):
                if not visited[num] and (num % pos == 0 or pos % num == 0):
                    visited[num] = True
                    bt(pos + 1)
                    visited[num] = False
        bt(1)
        return self.count

class Solution:
    def wordsAbbreviation(self, words: list[str]) -> list[str]:
        def abbr(word, k):
            if k + 2 >= len(word): return word
            return word[:k+1] + str(len(word)-k-2) + word[-1]
        n = len(words)
        prefix = [0] * n
        res = [abbr(words[i], 0) for i in range(n)]
        while True:
            groups = {}
            for i in range(n):
                groups.setdefault(res[i], []).append(i)
            changed = False
            for key, indices in groups.items():
                if len(indices) <= 1: continue
                changed = True
                for i in indices:
                    prefix[i] += 1
                    res[i] = abbr(words[i], prefix[i])
            if not changed: break
        return res

