class Solution:
    def updateBoard(self, board, click) -> list[list[str]]:
        r, c = click
        if board[r][c] == 'M':
            board[r][c] = 'X'
            return board
        m, n = len(board), len(board[0])
        def dfs(i, j):
            mines = 0
            for di in [-1,0,1]:
                for dj in [-1,0,1]:
