class Solution:
    def findBlackPixel(self, picture: list[list[str]], target: int) -> int:
        from collections import Counter
        m, n = len(picture), len(picture[0])
        rows = [''.join(r) for r in picture]
        row_count = Counter(rows)
        col_b = [sum(1 for i in range(m) if picture[i][j]=='B') for j in range(n)]
        count = 0
        for pattern, freq in row_count.items():
            if freq != target: continue
            for j in range(n):
                if pattern[j] == 'B' and col_b[j] == target:
                    count += target
        return count

